use crate::{model::*,unit_support::*,batch4_markers::MarkerKind as K};
#[test]fn wm031_first_actual_marker_forced_selection_and_wounds(){let mut g=game();let id=field(&mut g,"WM031",0);let other=field(&mut g,"JC125",1);g.place_board_markers(&id,K::Time,1);g.drive().unwrap();crate::jc029_tests::pass_top(&mut g);assert_eq!(g.pending.as_ref().unwrap().seat,0);choose(&mut g,vec![id.clone()]);assert_eq!(g.pending.as_ref().unwrap().seat,1);choose(&mut g,vec![other.clone()]);assert!(g.board(&id).is_none());assert!(g.board(&other).is_none());restore(&mut g);}
#[test]fn wm031_catalog_and_conditional_chaos(){let mut g=game();let id=field(&mut g,"WM031",0);assert!(!crate::catalog::card("WM031").supported);assert_current_serial_catalog();crate::rules::validate_definitions(crate::rules::definitions()).unwrap();assert!(!g.wm031_chaos(g.board(&id).unwrap().1));g.add_society_markers(0,1,0);assert!(g.wm031_chaos(g.board(&id).unwrap().1));}
fn recover(g:&mut Game){restore(g);let room=crate::jc029_tests::envelope(g);*g=crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&room).unwrap()).unwrap().game;}
fn finish(g:&mut Game){for _ in 0..100{if let Some(p)=g.pending.clone(){let ids=p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect();choose(g,ids);}else if !g.stack.is_empty(){pass(g);}else{g.drive().unwrap();if g.pending.is_none()&&g.stack.is_empty(){break}}}}
#[test]fn wm031_add_then_remove_repeated_categories_and_source_departure(){let mut g=game();let id=field(&mut g,"WM031",0);let target=field(&mut g,"JC125",1);g.place_board_markers(&id,K::Time,1);g.board_mut(&id).unwrap().time_markers=0;g.place_board_markers(&id,K::Shield,1);assert_eq!(g.effects.iter().filter(|e|matches!(e,Effect::Declare{declaration:d}if d.ability.key==crate::wm031::KEY)).count(),1);g.drive().unwrap();g.remove_dead(&id,RemovalCause::Destroy);recover(&mut g);finish(&mut g);assert!(g.board(&target).is_none());recover(&mut g);}
#[test]fn wm031_nested_other_demon_and_new_turn_first_are_independent(){let mut g=game();let a=field(&mut g,"WM031",0);let b=field(&mut g,"WM031",1);g.place_board_markers(&a,K::Time,1);g.drive().unwrap();finish(&mut g);assert!(g.board(&a).is_none());assert!(g.board(&b).is_none());assert_eq!(g.first_marker_placements.iter().filter(|e|e.carrier.definition=="WM031").count(),2);recover(&mut g);let c=field(&mut g,"WM031",0);g.place_board_markers(&c,K::Time,1);g.drive().unwrap();g.stack.clear();g.effects.clear();g.effect(Effect::NextTurn).unwrap();g.effects.clear();assert!(g.first_marker_placements.is_empty());g.place_board_markers(&c,K::Time,1);assert!(g.effects.iter().any(|e|matches!(e,Effect::Declare{declaration:d}if d.ability.key==crate::wm031::KEY)));}
#[test]fn wm031_hidden_first_not_retroactive_and_uncontrolled_targets_not_offered(){let mut g=game();let id=field(&mut g,"WM031",0);g.board_mut(&id).unwrap().face_down=true;g.place_board_markers(&id,K::Time,1);assert!(g.effects.is_empty());g.board_mut(&id).unwrap().face_down=false;g.place_board_markers(&id,K::Shield,1);assert!(g.effects.is_empty());let second=field(&mut g,"WM031",1);let hidden=field(&mut g,"JC125",2);g.board_mut(&hidden).unwrap().face_down=true;g.place_board_markers(&second,K::Time,1);g.drive().unwrap();crate::jc029_tests::pass_top(&mut g);let p=g.pending.clone().unwrap();assert!(p.choice.options.iter().all(|o|o.id!=hidden&&o.id!=second));let n=p.choice.id.clone();reject(&mut g,0,Action{choice_id:Some(n),selected:Some(vec![second]),..Action::new("choose")});recover(&mut g);}
#[test]fn wm031_corrupt_receipt_program_and_pending_reject_game_and_room(){let mut g=game();let id=field(&mut g,"WM031",0);g.place_board_markers(&id,K::Time,1);g.drive().unwrap();let corrupt=|g:Game|{assert!(Game::from_persisted(&serde_json::to_string(&g).unwrap()).is_err());let r=crate::room::RoomEnvelope::from_game(g);assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).is_err());};let mut bad=g.clone();bad.stack.last_mut().unwrap().frame.as_mut().unwrap().steps.clear();corrupt(bad);let mut bad=g.clone();bad.first_marker_placements.clear();corrupt(bad);crate::jc029_tests::pass_top(&mut g);let mut bad=g.clone();bad.pending.as_mut().unwrap().choice.min=Some(0);corrupt(bad);recover(&mut g);}

fn construct(seed:u64)->Game{use crate::{catalog,deck};let mut d=deck::preset("watchers").unwrap();d.id="closed-wm031-natural".into();d.society_id=Some("MSJC13".into());d.core_card_id=None;d.cards=[("WM031",3),("BQ090",3),("JC042",3),("JC049",3),("JC047",3),("XQ17",3),("JC045",3),("JC043",3),("JC048",3),("JC125",23)].into_iter().map(|(id,count)|catalog::DeckEntry{card_id:id.into(),count}).collect();assert!(deck::validate(d.clone()).is_err());let mut cards=catalog::catalog().cards.clone();cards.iter_mut().find(|c|c.id=="WM031").unwrap().supported=true;let mut societies=catalog::catalog().societies.clone();societies.iter_mut().find(|s|s.card.id=="MSJC13").unwrap().card.supported=true;let d=deck::validate_with_registry(d,&cards,&societies).unwrap();let mut other=deck::preset("watchers").unwrap();other.society_id=None;other.core_card_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();let mut g=Game::new("wm031-natural".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d,other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();g}
fn duplicate_trace(mut v:serde_json::Value)->serde_json::Value{for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(d.outcome,"rejected");assert_eq!(d.state,s["expected"]["state"]);s["duplicate"]=serde_json::to_value(d).unwrap();}v}
#[test]fn wm031_natural_deploy_then_paid_clock_marker_wound_export(){use crate::abi112_review_play_tests::Trace;let(seed,g)=(1..1025).find_map(|seed|{let g=construct(seed);g.players[0].hand.iter().any(|c|c.definition=="WM031").then_some((seed,g))}).unwrap();let deck=g.players[0].deck_snapshot.clone().unwrap();let mut t=Trace::new_preserving_rng(g,"wm031-natural-deploy-clock-marker-wound".into(),931);let(mut deployed,mut activated)=(false,false);for _ in 0..1800{let g=&t.room.game;if let Some(p)=g.pending.clone(){let ids=p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect();t.choose(ids);continue}if activated&&g.stack.is_empty()&&g.effects.is_empty(){break}if !g.stack.is_empty()||t.room.pacing.window.is_some(){t.pass();continue}let legal=g.legal_actions(0);let a=if g.players[0].assets.len()<2{legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition!="WM031"&&crate::catalog::card(&c.definition).color=="红")))}else if !deployed{legal.iter().find(|a|a.action.kind=="deploy"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition=="WM031")))}else{legal.iter().find(|a|a.action.ability_id.as_deref()==Some(crate::batch4_clock::ADD)&&a.action.target_id.as_ref().is_some_and(|id|g.in_play(id).is_some_and(|(_,c)|c.definition=="WM031")))};if let Some(a)=a{let a=a.action.clone();if a.kind=="deploy"{deployed=true}if a.ability_id.as_deref()==Some(crate::batch4_clock::ADD){activated=true}t.action(0,a);}else{t.pass();}}
assert!(deployed&&activated);assert!(t.room.game.players[0].graveyard.iter().any(|c|c.definition=="WM031"));let mut natural=t.value();natural["construction"]=serde_json::json!({"deck":deck,"seed":seed,"privateRegistryCandidates":["WM031","MSJC13"],"noLayoutOrResourceMutation":true});let mut g=game();let id=field(&mut g,"WM031",0);for seat in 1..4{field(&mut g,"JC125",seat);}g.place_board_markers(&id,K::Time,1);g.drive().unwrap();let mut t=Trace::new_preserving_rng(g,"wm031-prepared-four-player-response-choice".into(),932);for _ in 0..100{if let Some(p)=t.room.game.pending.clone(){t.choose(p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect());}else if !t.room.game.stack.is_empty()||t.room.pacing.window.is_some(){t.pass();}else{break}}assert!(t.room.game.regions.iter().all(|r|r.cards.is_empty()));let cases=vec![duplicate_trace(natural),duplicate_trace(t.value())];if let Ok(path)=std::env::var("WM031_NATIVE_OUT"){use sha2::{Digest,Sha256};let mut binding=crate::bq052_tests::source_bindings();for(n,s)in[("rust-game/src/wm031.rs",include_str!("wm031.rs")),("rust-game/src/wm031_tests.rs",include_str!("wm031_tests.rs")),("rust-game/src/marker_placement.rs",include_str!("marker_placement.rs"))]{binding["files"][n]=format!("{:x}",Sha256::digest(s.as_bytes())).into();}std::fs::write(path,serde_json::to_vec(&serde_json::json!({"catalog":crate::catalog::catalog(),"sourceBindings":binding,"cases":cases})).unwrap()).unwrap();}}

#[test]fn wm031_real_deploy_chaos_obeys_personal_exposure_not_initiative(){for exposed in [false,true]{let mut g=game();fund(&mut g,0,"JC049",2);let id=held(&mut g,"WM031",0);if exposed{g.add_society_markers(0,1,0);}let actions=g.legal_actions(0);let deploy=actions.iter().filter(|a|a.action.kind=="deploy"&&a.action.card_id.as_ref()==Some(&id)).collect::<Vec<_>>();assert!(!deploy.is_empty());assert!(deploy.iter().all(|a|a.action.region.is_none()==exposed));let a=deploy[0].action.clone();act(&mut g,0,a);crate::jc029_tests::pass_top(&mut g);assert!(g.regions.iter().flat_map(|r|&r.cards).any(|c|c.definition=="WM031"));recover(&mut g);}}
#[test]fn wm031_duplicate_declaration_and_skipped_previous_player_rejected(){let mut g=game();let id=field(&mut g,"WM031",0);field(&mut g,"JC125",1);g.place_board_markers(&id,K::Time,1);let mut bad=g.clone();let d=bad.effects.back().unwrap().clone();bad.effects.push_back(d);assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());g.drive().unwrap();crate::jc029_tests::pass_top(&mut g);choose(&mut g,vec![id]);let mut bad=g.clone();if let ChoiceResolution::Frame{choice:FrameChoice::WM031Victims(v),..}=&mut bad.pending.as_mut().unwrap().resolution{v.selected.clear();}assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());recover(&mut g);}
